const items = $input.all();

return items.map(item => {
  const data = item.json;

  // Processor check: i5 or higher passes
  const processor = String(data["Processor"]).toLowerCase();
  const processorPass =
    processor.includes("i5") ||
    processor.includes("i7") ||
    processor.includes("i9");

  // Check for missing required information
  const missingInformation = [];

  const requiredFields = [
    "Supplier ID",
    "Supplier Name",
    "Product",
    "Quantity",
    "Total Price",
    "Delivery Time Days",
    "Warranty Years",
    "RAM GB",
    "Storage GB",
    "Processor",
    "Operating System",
    "Payment Terms"
  ];

  for (const field of requiredFields) {
    if (
      data[field] === undefined ||
      data[field] === null ||
      data[field] === ""
    ) {
      missingInformation.push(field);
    }
  }

  // Deterministic compliance checks
  const complianceChecks = {
    budget: Number(data["Total Price"]) <= Number(data["Maximum Budget"]),

    quantity: Number(data["Quantity"]) === 25,

    delivery:
      Number(data["Delivery Time Days"]) <=
      Number(data["Required Delivery Days"]),

    warranty:
      Number(data["Warranty Years"]) >=
      Number(data["Minimum Warranty Years"]),

    ram:
      Number(data["RAM GB"]) >=
      Number(data["Minimum RAM GB"]),

    storage:
      Number(data["Storage GB"]) >=
      Number(data["Minimum Storage GB"]),

    processor: processorPass,

    operatingSystem:
      data["Operating System"] === "Licensed Windows 11 Pro",

    paymentTerms:
      data["Payment Terms"] === data["Payment Preference"]
  };

  const allChecksPassed =
    Object.values(complianceChecks).every(check => check === true) &&
    missingInformation.length === 0;

  item.json["Compliance Checks"] = complianceChecks;
  item.json["Missing Information"] = missingInformation;
  item.json["Compliance Status"] =
    allChecksPassed ? "Compliant" : "Non-Compliant";

  return item;
});

