const items = $input.all();

return items.map(item => {
const data = item.json;

let recommendation;

try {
recommendation = typeof data.output === 'string'
? JSON.parse(data.output)
: data.output;
} catch (error) {
throw new Error('Could not parse the recommendation JSON.');
}

const attempt = Number(data.Attempt || 3);

const supplier = recommendation["Recommended Supplier Name"] || "N/A";
const supplierId = recommendation["Recommended Supplier ID"] || "N/A";
const product = recommendation["Recommended Product"] || "N/A";
const totalPrice = recommendation["Recommended Total Price"] ?? "N/A";
const status = recommendation["Recommendation Status"] || "N/A";
const compliance = recommendation["Recommended Compliance Status"] || "N/A";
const reason = recommendation["Recommendation Reason"] || "N/A";
const strengths = recommendation["Key Strengths"] || [];
const risks = recommendation["Key Risks"] || [];
const approvalRequired = recommendation["Manager Approval Required"] ? "Yes" : "No";

const strengthsHtml = strengths.length
? `<ul>${strengths.map(x => `<li>${x}</li>`).join('')}</ul>`
: '<p>N/A</p>';

const risksHtml = risks.length
? `<ul>${risks.map(x => `<li>${x}</li>`).join('')}</ul>`
: '<p>N/A</p>';

const email_body = `

<p>Dear Operations Manager,</p>

<p>The previous supplier recommendation was declined. A re-evaluation has therefore been completed.</p>

<p><strong>Re-evaluation Attempt:</strong> ${attempt}</p>

<p><strong>Recommended Supplier</strong></p>
<ul>
  <li><strong>Supplier:</strong> ${supplier}</li>
  <li><strong>Supplier ID:</strong> ${supplierId}</li>
  <li><strong>Product:</strong> ${product}</li>
  <li><strong>Total Price:</strong> NPR ${Number(totalPrice).toLocaleString()}</li>
  <li><strong>Recommendation Status:</strong> ${status}</li>
  <li><strong>Compliance Status:</strong> ${compliance}</li>
  <li><strong>Manager Approval Required:</strong> ${approvalRequired}</li>
</ul>

<p><strong>Recommendation Reason</strong></p>
<p>${reason}</p>

<p><strong>Key Strengths</strong></p>
${strengthsHtml}

<p><strong>Key Risks</strong></p>
${risksHtml}

<p>Please review the re-evaluated recommendation and provide your approval or rejection.</p>

<p>Regards,<br>
Supplier Evaluation System<br>
Everest Manufacturing Operations</p>
`;

return {
json: {
email_body,
Attempt: attempt
}
};
});
